import static org.junit.Assert.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.Test;
import com.seriouscompany.business.java.slopfizzbuzz.packagenamingpackage.impl.precedent.*;
import com.seriouscompany.business.java.slopfizzbuzz.packagenamingpackage.impl.precedent.PriorWorkDocuments.*;
import com.seriouscompany.business.java.slopfizzbuzz.packagenamingpackage.impl.proceedings.*;

public class PriorWorkCourtTest {
 @Test public void unsupportedJurisdictionsAndAbsentTextHaveExplicitObjections(){for(int limit:new int[]{-1,Integer.MIN_VALUE,1001,Integer.MAX_VALUE}){PrecedentDossier d=PriorWorkRatificationDirectorate.standard().inspect(new Petition(limit,limit,""),"MANDATE");assertFalse(d.isApproved());assertEquals("REJECTED",d.getSteps().get(1).state);}PrecedentDossier absent=PriorWorkRatificationDirectorate.standard().inspect(new Petition(3,3,null),"MANDATE");assertEquals("REJECTED",absent.getSteps().get(0).state);}
 @Test public void unavailableCourtIsABypassRatherThanALicensedOrSubstantivelyRejectedHit(){PriorWorkRatificationDirectorate closed=new PriorWorkRatificationDirectorate(new PrecedentAdmissionOffice(){public Admission admit(Petition p){throw new IllegalStateException("court closed");}},null,null,null,null);com.seriouscompany.business.java.slopfizzbuzz.packagenamingpackage.impl.cache.CacheAuthority cache=new com.seriouscompany.business.java.slopfizzbuzz.packagenamingpackage.impl.cache.CacheAuthority(new com.seriouscompany.business.java.slopfizzbuzz.packagenamingpackage.impl.cache.CacheRepository(){public boolean enabled(){return true;}public String get(int n){return EveryPriorWorkPetitionTest.oracle(n);}public void put(int n,String text,int ttl){}},closed);com.seriouscompany.business.java.slopfizzbuzz.packagenamingpackage.impl.cache.CacheLookup result=cache.lookup(3);assertEquals(com.seriouscompany.business.java.slopfizzbuzz.packagenamingpackage.impl.cache.CacheLookup.State.BYPASS,result.getState());assertNull(result.getPrecedent());assertTrue(cache.statusJson().contains("\"errors\":1"));assertTrue(cache.statusJson().contains("\"rejectedPrecedents\":0"));}
 @Test public void portableObjectionsSurviveEveryCompiler(){assertTrue(PriorWorkObjectionTribunal.rehearse()>110);}
 @Test public void allFiveOfficesAreReplaceableAndActuallyCalled(){final List<String> calls=new ArrayList<String>();PriorWorkRatificationDirectorate court=new PriorWorkRatificationDirectorate(
  new PrecedentAdmissionOffice(){public Admission admit(Petition p){calls.add("admit");return new BoundedPrecedentAdmissionOffice().admit(p);}},
  new MandateJurisdictionChamber(){public Jurisdiction review(Admission a){calls.add("scope");return new ExactMandateJurisdictionChamber().review(a);}},
  new CompletenessInventoryOffice(){public Inventory count(Jurisdiction j){calls.add("count");return new CompleteLineInventoryOffice().count(j);}},
  new IndependentLexicalBench(){public Inspection inspect(Inventory i){calls.add("inspect");return new NotarialIndependentLexicalBench().inspect(i);}},
  new NonPerformanceLicensingAuthority(){public License authorize(Inspection i){calls.add("license");return new IndependentlyAuditedNonPerformanceAuthority().authorize(i);}});
  assertTrue(court.inspect(new Petition(3,3,EveryPriorWorkPetitionTest.oracle(3)),"MANDATE").isApproved());assertEquals(Arrays.asList("admit","scope","count","inspect","license"),calls);
 }
 @Test public void currentDecisionsAreObservedOnceAndDownstreamOfficesStayAbsent(){BoundedExecutionLedger ledger=new BoundedExecutionLedger();try(ExecutionCustody.Capture capture=ExecutionCustody.capture(ledger)){assertFalse(PriorWorkRatificationDirectorate.rehearse("wrong-mandate").isApproved());}String json=ledger.toJson();assertTrue(json.contains("Precedent Admission Office"));assertTrue(json.contains("Mandate Jurisdiction Chamber"));assertFalse(json.contains("Non-Performance Licensing Authority"));}
 @Test public void concurrentIdenticalCasesNeverShareTheirIssuedDocuments()throws Exception{ExecutorService pool=Executors.newFixedThreadPool(6);final PriorWorkRatificationDirectorate court=PriorWorkRatificationDirectorate.standard();try{List<Future<String>> results=new ArrayList<Future<String>>();for(int n=0;n<100;n++){final int limit=n;results.add(pool.submit(new Callable<String>(){public String call(){String expected=EveryPriorWorkPetitionTest.oracle(limit);return court.inspect(new Petition(limit,limit,expected),"MANDATE").authorizedBody();}}));}for(int n=0;n<100;n++)assertEquals(EveryPriorWorkPetitionTest.oracle(n),results.get(n).get(10,TimeUnit.SECONDS));}finally{pool.shutdownNow();}}
 @Test public void hostileFilesHaveBoundedAsciiDecisions(){for(String body:new String[]{"1\n2\n\uD83D\uDE31\n","<script>alert(1)</script>\n","1\u0000\n2\nFizz\n"}){PrecedentDossier d=PriorWorkRatificationDirectorate.standard().inspect(new Petition(3,3,body),"MANDATE");assertFalse(d.isApproved());assertTrue(d.toJson().matches("[\\x20-\\x7e]*"));assertFalse(d.toJson().contains("<script>"));}}
 @Test public void aRejectedDossierCannotDiscloseTheRejectedBody(){try{PriorWorkRatificationDirectorate.rehearse("lowercase-fizz").authorizedBody();fail("No license exists");}catch(IllegalStateException expected){assertTrue(expected.getMessage().contains("license"));}}
}
